-- NANG CAP NOI DUNG WEBSITE: 39 bang -> 41 bang.
-- Chon database dang dung (english_center_db) trong phpMyAdmin truoc khi Import.
-- Khong xoa bang, khong reset tai khoan, giu nguyen noi dung da sua.
SET NAMES utf8mb4;

CREATE TABLE IF NOT EXISTS `public_teachers` (`id` bigint unsigned NOT NULL AUTO_INCREMENT,`name` varchar(255) NOT NULL,`slug` varchar(255) NOT NULL,`bio` text NOT NULL,`photo_path` varchar(255) NOT NULL,`provider` varchar(50) NOT NULL,`source_url` varchar(500) NULL,`qualifications` json NULL,`position` int unsigned NOT NULL DEFAULT 0,`is_active` tinyint(1) NOT NULL DEFAULT 1,`created_at` timestamp NULL,`updated_at` timestamp NULL,PRIMARY KEY (`id`),UNIQUE KEY `public_teachers_slug_unique` (`slug`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `site_settings` (`id` bigint unsigned NOT NULL AUTO_INCREMENT,`key` varchar(255) NOT NULL,`value` json NOT NULL,`created_at` timestamp NULL,`updated_at` timestamp NULL,PRIMARY KEY (`id`),UNIQUE KEY `site_settings_key_unique` (`key`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

START TRANSACTION;
COMMIT;
