INSERT INTO `public_teachers` (`name`,`slug`,`bio`,`photo_path`,`provider`,`source_url`,`qualifications`,`position`,`is_active`,`created_at`,`updated_at`) VALUES ('Thầy Jackson Howard','prep-jackson-howard','Giáo viên được giới thiệu trong chương trình IELTS của PREP. Thông tin chuyên môn dưới đây theo hồ sơ công khai của PREP.','images/teachers/prep-33.png','PREP','https://prepedu.com/vi/ielts#teacher','["Thạc sĩ TESOL.","PREP giới thiệu kinh nghiệm giám khảo IELTS tại IDP và British Council."]',1,1,'2026-10-22 05:18:43','2026-10-22 05:18:43') ON DUPLICATE KEY UPDATE `id`=`public_teachers`.`id`;
INSERT INTO `public_teachers` (`name`,`slug`,`bio`,`photo_path`,`provider`,`source_url`,`qualifications`,`position`,`is_active`,`created_at`,`updated_at`) VALUES ('Cô Trang Trương','prep-trang-truong','Giáo viên IELTS được giới thiệu trên trang PREP, có nền tảng đào tạo về tiếng Anh và quan hệ quốc tế.','images/teachers/prep-12.png','PREP','https://prepedu.com/vi/ielts#teacher','["Thạc sĩ tại Đại học Antwerp, Bỉ.","Có chứng chỉ CELTA loại A và DELTA Module 1, theo PREP."]',2,1,'2026-10-22 05:18:43','2026-10-22 05:18:43') ON DUPLICATE KEY UPDATE `id`=`public_teachers`.`id`;
INSERT INTO `public_teachers` (`name`,`slug`,`bio`,`photo_path`,`provider`,`source_url`,`qualifications`,`position`,`is_active`,`created_at`,`updated_at`) VALUES ('Cô Quỳnh Nguyễn','prep-quynh-nguyen','Theo PREP, cô là cựu giáo viên từng tham gia sản xuất khóa học IELTS tại PREP.','images/teachers/prep-5.png','PREP','https://prepedu.com/vi/ielts#teacher','["Thạc sĩ tại UCL, London.","Nhận học bổng Chevening, theo hồ sơ PREP."]',3,1,'2026-10-22 05:18:43','2026-10-22 05:18:43') ON DUPLICATE KEY UPDATE `id`=`public_teachers`.`id`;
INSERT INTO `site_settings` (`key`,`value`,`created_at`,`updated_at`) VALUES ('home','{"title":"Học tiếng Anh, cùng lộ trình phù hợp.","description":"Khám phá chương trình học và luyện tập mỗi ngày cùng English Center.","image":"images/catalog/study4/study-banner.jpg","teacher_title":"Gặp gỡ đội ngũ giáo viên","teacher_description":"Tìm hiểu hồ sơ và chuyên môn của các giáo viên được giới thiệu từ PREP."}','2026-10-22 05:18:43','2026-10-22 05:18:43') ON DUPLICATE KEY UPDATE `id`=`site_settings`.`id`;
